insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c01', '빗길, 미끄럼방지 포장 구간에서 버스가 가드레일을 들이받고 추락 (경남 함양)', '맨 인 블랙박스 (SBS) 44회', '2017-07-16', 'SBS 프로그램 소개 - 44회', 'https://programs.sbs.co.kr/programTemplate/amp/vod/maninblackbox/22000237200', 'rain', 'general', '빗길에서 버스가 미끄러져 가드레일을 들이받고 추락했다. 미끄럼방지 포장이 제 기능을 잃어 마찰계수가 일반 도로(82)보다 낮은 38로 측정됐다.', '미끄럼방지 포장의 마찰력 상실', null, '비 오는 날에는 포장 상태에 따라 마찰력이 크게 달라질 수 있다. 평소보다 감속하고 급제동·급핸들을 피한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c02', '비만 오면 화단으로 돌진하는 사고가 반복된 도로', '맨 인 블랙박스 (SBS) 44회', '2017-07-16', 'SBS 프로그램 소개 - 44회', 'https://programs.sbs.co.kr/programTemplate/amp/vod/maninblackbox/22000237200', 'rain', 'general', '과속이 없었는데도 비가 오면 차량이 미끄러져 화단으로 돌진하는 사고가 수십 건 발생했다. 마모된 미끄럼방지 포장이 일반 아스팔트보다 더 미끄러운 것으로 소개됐다.', '마모된 미끄럼방지 포장, 도로 관리 부실', null, '사고가 잦은 구간은 과속이 아니어도 위험하다. 노면이 번들거리거나 마모된 구간은 우천 시 특히 감속한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c03', '중앙선 없는 굽은 산길에서 정면충돌, 과실 다툼', '맨 인 블랙박스 (SBS) 562·563회', '2024-01-28', 'SBS 프로그램 소개 - 562·563회', 'https://programs.sbs.co.kr/programTemplate/amp/vod/maninblackbox/22000521294', 'unknown', 'mountain', '중앙선이 없는 굽이진 산길에서 마주 오던 차와 정면충돌했다. 굽은 도로라 맞은편 차를 미리 보기 어려웠고, 상대 차는 좌측으로 바짝 붙어 주행했다.', '굽은 도로의 시야 제한, 상대 차량의 좌측 쏠림 주행', null, '중앙선 없는 굽은 산길에서는 차로 우측으로 붙어 저속 주행하고, 시야가 막힌 커브 앞에서는 충분히 감속한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c04', '밤새 내린 눈, 가파른 내리막에서 제동 중 미끄러져 불법주차 차량 충돌', '맨 인 블랙박스 (SBS) 562·563회', '2024-01-28', 'SBS 프로그램 소개 - 562·563회', 'https://programs.sbs.co.kr/programTemplate/amp/vod/maninblackbox/22000521294', 'snow', 'slope', '눈 쌓인 가파른 내리막길에서 제동하던 차량이 미끄러져 앞쪽의 불법 주차 차량을 들이받았다.', '눈길 제동 중 미끄러짐, 내리막 앞 불법 주차', null, '눈길 내리막에서는 진입 전에 속도를 줄이고 엔진브레이크를 활용한다. 제동은 미리, 부드럽게 한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c05', '눈보라 속 제설차 역주행을 피하다 가로수 충돌', '맨 인 블랙박스 (SBS) 562·563회', '2024-01-28', 'SBS 프로그램 소개 - 562·563회', 'https://programs.sbs.co.kr/programTemplate/amp/vod/maninblackbox/22000521294', 'snow', 'slope', '눈 덮인 가파른 내리막에서 제설차가 중앙선을 넘어 역주행하자 이를 피하던 차량이 가로수를 들이받았다. 제설차는 긴급자동차로 분류되어 좌측 통행이 가능하다고 설명됐다.', '제설차의 중앙선 침범 주행에 대한 회피 조작', null, '눈길에서는 제설 작업 차량이 반대 차로로 올 수 있다고 예상한다. 속도를 줄이고 정지할 수 있는 여유 거리를 둔다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c06', '제한속도 40km/h 램프 곡선 구간을 약 70km/h로 달리다 가드레일 충돌', '맨 인 블랙박스 (SBS) 182회', '2019-02-17', 'SBS 프로그램 소개 - 182·183회', 'https://programs.sbs.co.kr/programTemplate/amp/vod/maninblackbox/22000319458', 'unknown', 'curve', '램프 곡선 구간에서 제한속도(40km/h)를 크게 넘긴 약 70km/h로 주행하다 중심을 잃고 가드레일을 들이받았다.', '곡선 구간 과속', '곡선 구간에서는 규정 속도 이하로 주행하고, 곡선반경에 맞는 제한속도 안내 표지판 설치가 중요하다고 소개됐다.', '곡선 구간은 직선과 같은 속도로 통과하지 않는다. 진입 전에 속도를 줄이고 커브 중간에서는 제동하지 않는다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c07', '약 90도 급커브를 추월하며 과속하다 중앙화단·연석 충돌', '맨 인 블랙박스 (SBS) 182회', '2019-02-17', 'SBS 프로그램 소개 - 182·183회', 'https://programs.sbs.co.kr/programTemplate/amp/vod/maninblackbox/22000319458', 'unknown', 'curve', '급하게 굽은 도로에서 추월하려고 과속으로 커브를 돌다 단독으로 중앙화단과 연석을 들이받았다.', '급커브에서의 추월 시도와 과속', '곡선 구간에 제한속도 안내 표지판을 설치해야 한다고 소개됐다.', '급커브 구간에서는 추월을 하지 않는다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c08', '방향지시등 없이 3차로에서 1차로로 변경하다 중앙분리대 충돌 (고속도로)', '맨 인 블랙박스 (SBS) 182회', '2019-02-17', 'SBS 프로그램 소개 - 182·183회', 'https://programs.sbs.co.kr/programTemplate/amp/vod/maninblackbox/22000319458', 'unknown', 'highway', '고속도로에서 방향지시등 없이 3차로에서 1차로로 한 번에 차로를 바꾸다 중앙분리대를 들이받았다.', '방향지시등 미사용, 급격한 차로 변경', null, '차로 변경은 방향지시등을 먼저 켜고, 한 차로씩 여유를 두고 변경한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c09', '정체 구간에서 트럭이 속도를 줄이지 않고 차로를 바꾸다 4중 추돌', '맨 인 블랙박스 (SBS) 182회', '2019-02-17', 'SBS 프로그램 소개 - 182·183회', 'https://programs.sbs.co.kr/programTemplate/amp/vod/maninblackbox/22000319458', 'unknown', 'general', '정체 구간에서 트럭이 속도를 줄이지 않은 채 차로 변경을 시도해 4중 추돌이 일어났다.', '정체 구간에서 감속 없는 차로 변경', null, '대형 차량은 제동거리가 길다. 정체 구간 접근 시 미리 감속하고 안전거리를 확보한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c10', '어두운 고속도로에서 비상등 없이 방치된 사고 차량을 피하다 중앙분리대 충돌', '맨 인 블랙박스 (SBS) 183회', '2019-02-17', 'SBS 프로그램 소개 - 182·183회', 'https://programs.sbs.co.kr/programTemplate/amp/vod/maninblackbox/22000319458', 'night', 'highway', '어둠 속 고속도로에 비상등 없이 방치된 사고 차량을 뒤늦게 발견하고 회피하다 중앙분리대를 들이받았다.', '고장·사고 차량의 비상등 미작동, 야간 시인성 저하', '비상등의 올바른 사용과 관련 법안·대책 마련이 필요하다고 소개됐다.', '야간 고속도로에서 고장 차량을 만나면 즉시 비상등과 삼각대(안전표지)로 후방에 알리고 안전한 곳으로 대피한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c11', '화물차가 방향지시등 대신 비상등을 켠 채 급하게 진입해 충돌', '맨 인 블랙박스 (SBS) 183회', '2019-02-17', 'SBS 프로그램 소개 - 182·183회', 'https://programs.sbs.co.kr/programTemplate/amp/vod/maninblackbox/22000319458', 'unknown', 'general', '4차로 도로에서 화물차가 방향지시등 대신 비상등을 켜고 급하게 차로에 진입해 충돌이 발생했다.', '신호 방법 오류와 급진입', null, '비상등은 방향지시등을 대신하지 못한다. 합류·차로 변경 때는 방향지시등으로 의도를 알린다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c12', '야간 고속도로에서 내비게이션 지시를 따르다 중앙분리대·가드레일 연속 충돌', '맨 인 블랙박스 (SBS) 56회', '2017-10-22', 'SBS 프로그램 소개 - 56·57회', 'https://programs.sbs.co.kr/programTemplate/amp/vod/maninblackbox/22000248844', 'night', 'highway', '야간 고속도로에서 제보자 차량을 피하려던 차량이 중앙분리대와 가드레일에 연속으로 충돌했다. 방송은 원인으로 내비게이션을 지목했다(구체적 설명은 소개글에 없음).', '내비게이션 지목 (세부 내용 미확인)', null, '야간에는 내비게이션 조작·확인에 시선을 오래 두지 않는다. 경로는 출발 전에 확인한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c13', '대형 트럭이 사각지대의 옆 차선 차량을 보지 못하고 차로 변경 충돌', '맨 인 블랙박스 (SBS) 56회', '2017-10-22', 'SBS 프로그램 소개 - 56·57회', 'https://programs.sbs.co.kr/programTemplate/amp/vod/maninblackbox/22000248844', 'unknown', 'general', '대형 트럭이 차로를 바꾸는 중 사각지대에 있던 옆 차선 차량을 보지 못해 충돌했다.', '대형 차량의 사각지대', null, '군용 트럭·버스 등 대형 차량은 사각지대가 넓다. 차로 변경 전 미러 확인과 육안 확인을 병행하고, 필요하면 유도원을 둔다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c14', '폭설이 내린 지하차도에서 역방향으로 서 있던 사고 차량을 피하다 미끄러진 2차 충돌', '한문철의 블랙박스 리뷰 (한블리)', '2026-01-21', '스타뉴스 - 한블리 방송 기사', 'https://www.starnewskorea.com/broadcast-show/2026/01/21/2026012109163183804', 'snow', 'underpass', '겨울철 폭설 중 지하차도에서 블랙박스 차량이 역방향으로 멈춰 있던 차량을 피하려다 미끄러져 뒤따르던 차량과 2차 충돌했다. 해당 차량은 3시간 전 사고 후 방치된 상태였다고 소개됐다.', '사고 후 방치된 차량, 폭설로 미끄러운 노면', null, '눈 오는 날 지하차도 진입 전에는 감속하고, 전방 정차 차량이 있을 때 급핸들 대신 미리 제동 여유를 확보한다. 사고 차량은 반드시 안전하게 이동·표시한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c15', '갑작스러운 폭설, 결빙된 언덕을 오르다 미끄러져 마주 오던 택시와 충돌', '한문철의 블랙박스 리뷰 (한블리)', '2025-12-17', '스타뉴스 - 한블리 방송 기사', 'https://www.starnewskorea.com/broadcast-show/2025/12/17/2025121709064097557', 'ice', 'slope', '갑작스러운 폭설과 노면 결빙으로 언덕을 오르던 블랙박스 차량이 미끄러져 마주 오던 택시와 충돌했다.', '폭설과 노면 결빙, 언덕 구간', null, '결빙된 오르막·내리막은 진입 자체를 피하거나 체인 등 월동장비를 갖추고 저속으로 통과한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c16', '폭설 속 미끄러지는 차량을 피하다 중앙분리대 충돌', '한문철의 블랙박스 리뷰 (한블리)', '2025-12-17', '스타뉴스 - 한블리 방송 기사', 'https://www.starnewskorea.com/broadcast-show/2025/12/17/2025121709064097557', 'snow', 'general', '눈길에서 미끄러지는 차량을 피하려던 차량이 중앙분리대를 들이받았다.', '눈길 미끄러짐 차량 회피', null, '눈길에서는 앞차와의 간격을 평소보다 크게 둬서 앞차가 미끄러져도 대응할 시간을 확보한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c17', '폭설 속 40중 추돌', '한문철의 블랙박스 리뷰 (한블리)', '2025-12-17', '스타뉴스 - 한블리 방송 기사', 'https://www.starnewskorea.com/broadcast-show/2025/12/17/2025121709064097557', 'snow', 'general', '미끄러운 겨울철 도로에서 40대가 얽힌 연쇄 추돌이 소개됐다. 기사는 겨울철 감속의 중요성을 강조했다.', '미끄러운 노면 (개별 원인 세부 내용 미확인)', null, '다수 차량이 이동하는 군 수송대는 앞차와의 차간 거리를 일반 기준보다 더 크게 유지하고 속도를 통일한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c18', '전통시장 좁은 골목에 트럭이 돌진한 부천 제일시장 사고', '한문철의 블랙박스 리뷰 (한블리)', '2025-12-17', '스타뉴스 - 한블리 방송 기사', 'https://www.starnewskorea.com/broadcast-show/2025/12/17/2025121709064097557', 'unknown', 'urban', '차량과 보행자가 뒤섞이는 시장 골목에서 트럭이 보행자와 상가로 돌진해 4명이 숨지고 17명이 다쳤다. 운전자는 브레이크 고장을 주장했으나, 기사는 페달 블랙박스에서 가속페달을 밟은 정황이 보도됐다고 전했다.', '운전자는 브레이크 고장을 주장 (기사는 가속페달 정황 보도를 전함)', '한문철 변호사는 대형 사고 예방 장치·제도와 인구 밀집 생활권의 교통안전 대책이 시급하다고 언급했다.', '보행자와 차량이 섞이는 구간에서는 서행하고, 출발 전 제동장치 점검과 페달 오조작 방지를 습관화한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c19', '새벽 출근 시간 신호 변경 직후 덤프트럭이 앞차를 들이받은 돌진 추돌', '한문철의 블랙박스 리뷰 (한블리)', '2026-02-11', '스타뉴스 - 한블리 방송 기사', 'https://www.starnewskorea.com/broadcast-show/2026/02/11/2026021115131988489', 'night', 'urban', '새벽 출근 시간대 신호가 바뀐 뒤 출발한 차량을 덤프트럭이 뒤에서 들이받았다. 트럭 운전자는 브레이크 고장을 주장하며 경적을 울렸다고 했지만 후방 블랙박스에는 경적 소리가 담기지 않았다. 원인은 규명되지 않은 상태로 소개됐다.', '미규명 (운전자는 브레이크 고장 주장)', null, '대형 차량은 운행 전 제동장치·공기압 점검이 필수다. 정비 불량은 사고 직전에 수습할 수 없다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c20', '갓길에 서 있던 차가 뒤를 확인하지 않고 진입해, 놀란 차량이 급가속하며 주택 충돌', '한문철의 블랙박스 리뷰 (한블리)', null, 'MBC 연예뉴스 - 한블리 방송 기사', 'https://enews.imbc.com/News/ViewAmp/484433', 'unknown', 'general', '갓길에 정차했던 차량이 후방을 확인하지 않고 무리하게 도로로 진입했다. 놀란 운전자가 급가속하며 반대편 주택을 들이받았다.', '후방 미확인 진입, 이에 놀란 운전자의 급가속', '한문철 변호사는 도로에 진입할 때는 반드시 뒤쪽을 확인해야 한다고 강조했다.', '갓길이나 부대 진입로에서 본선에 합류할 때는 정지 후 좌우·후방을 확인하고 진입한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c21', '시골길에 약 100마리 흑염소 떼가 나타나 도로를 막은 상황', '한문철의 블랙박스 리뷰 (한블리)', null, 'MBC 연예뉴스 - 한블리 방송 기사', 'https://enews.imbc.com/News/ViewAmp/484433', 'unknown', 'mountain', '시골길에서 약 100마리의 흑염소 떼가 차량 앞을 가로막았다. 블랙박스 차량이 서행 중이었고 주변에 다른 차가 없어 사고는 피했다고 소개됐다.', '가축·동물의 도로 출현', null, '산간·농촌 도로에서는 동물이 갑자기 나타날 수 있다. 시야가 막힌 구간에서는 서행하여 즉시 정지할 수 있는 속도를 유지한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c22', '신호등 없는 교차로에서 좌회전 차량이 직진 오토바이를 들이받고 지나간 역과 사고', '한문철의 블랙박스 리뷰 (한블리)', '2026-05-13', '스타뉴스 - 한블리 방송 기사', 'https://www.starnewskorea.com/broadcast-show/2026/05/13/2026051309035218705', 'unknown', 'urban', '신호등 없는 교차로에서 좌회전 차량이 직진하던 오토바이를 들이받은 뒤 멈추지 않고 쓰러진 피해자를 밟고 지나갔다.', '좌회전 차량의 충돌 후 정지 의무 위반', '한문철 변호사는 피해자로서는 도저히 피할 수 없었던 사고라고 분석하며 신호등 없는 교차로 사고의 위험성을 경고했다.', '신호 없는 교차로는 일단 감속해 직진 차량·이륜차를 먼저 보내고 통과한다. 사고가 나면 즉시 정지하고 구호 조치한다.');
insert into public.cases (id,title,program,date,source_title,source_url,weather,road_type,summary,cause,advice,lesson) values ('c23', '음주 상태로 가다 서기를 반복하다 앞차 후미 추돌, 피해 차량 전복', '한문철의 블랙박스 리뷰 (한블리)', null, 'MBC 연예뉴스 - 한블리 방송 기사', 'https://enews.imbc.com/News/ViewAmp/425514', 'unknown', 'general', '가해 차량이 가다 서기를 반복하고 차선을 넘나들다 앞차 후미를 들이받았고 피해 차량은 한 바퀴 이상 전복됐다. 가해 운전자는 면허 취소 수준의 음주 상태였던 것으로 소개됐다.', '음주운전', null, '음주 후에는 절대 운전하지 않는다. 전날 음주 후 숙취 상태의 운전도 금지하고, 부대 복귀 시에는 대리운전·대중교통을 이용한다.');
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z01', '대관령 영동고속도로 구간', '강원 평창·강릉', 37.69, 128.72, 'highway', array['snow', 'ice', 'fog']::text[], 5, '해발이 높고 급경사·급커브가 이어지는 산악 고속도로 구간. 겨울철 적설과 결빙, 안개가 겹치기 쉽다.', array['내리막 연속 구간에서 제동 과열·미끄러짐', '그늘진 곳의 블랙아이스', '안개로 인한 시정 불량']::text[], array['진입 전 월동장비(체인) 확인', '내리막에서는 엔진브레이크 사용', '앞차와의 거리를 평소의 2배 이상 확보']::text[], '대형 군용차량은 무게 때문에 내리막 제동거리가 길다. 수송대 편성 시 차간 거리를 넓히고 선두에서 속도를 통제한다.', array['c04', 'c15', 'c05']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z02', '한계령 굽은 산악도로', '강원 인제·양양', 38.12, 128.3, 'mountain', array['snow', 'ice', 'fog']::text[], 5, '굽이진 도로가 길게 이어지는 산악 구간. 눈·결빙·안개가 잦아 겨울철 통제가 빈번하다.', array['연속 급커브에서 중앙선 침범', '안개로 맞은편 차량 인지 지연', '노면 결빙']::text[], array['커브 진입 전 감속, 커브 중 제동 금지', '차로 우측으로 붙어 주행', '기상 통제 정보 사전 확인']::text[], '전방지역으로 이동하는 부대 차량이 이용하는 경우가 있어 기상 악화 시 출발 시각 조정과 경로 변경을 우선 검토한다.', array['c03', 'c06', 'c07']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z03', '미시령 구간', '강원 인제·고성', 38.14, 128.4, 'mountain', array['snow', 'ice', 'fog']::text[], 4, '고갯길 특성상 강풍과 적설, 안개가 겹쳐 시정과 노면 상태가 급변한다.', array['급변하는 기상', '강풍으로 인한 차체 흔들림', '결빙된 오르막·내리막']::text[], array['출발 전 기상·통제 확인', '저단 기어로 일정 속도 유지', '정차 시 안전한 갓길 확보']::text[], '높이가 큰 군용 트럭은 측풍에 취약하므로 강풍 시 속도를 낮춘다.', array['c04', 'c05', 'c15']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z04', '서해대교·서평택 일대', '경기 평택 ~ 충남 당진', 36.97, 126.82, 'bridge', array['fog', 'rain']::text[], 4, '해안 교량 구간으로 안개가 자주 끼고 바람이 강하다. 시정이 급격히 나빠지면 연쇄 추돌 위험이 커진다.', array['짙은 안개에서의 시정 불량', '교량 위 측풍', '앞차 급정지로 인한 연쇄 추돌']::text[], array['안개등·전조등 점등', '가시거리 100m 이내면 평소 속도의 절반으로 감속', '차로 변경 금지, 앞차 후미등을 기준으로 간격 유지']::text[], '수송대는 안개 시 선두 차량이 속도를 정하고 뒤차는 간격을 유지한다. 무리한 연속 주행은 피한다.', array['c09', 'c16', 'c17']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z05', '인천대교 일대', '인천 송도 ~ 영종', 37.38, 126.6, 'bridge', array['fog', 'rain']::text[], 3, '바다 위를 지나는 장대 교량으로 안개와 강풍의 영향이 크다.', array['안개로 인한 시정 불량', '교량 이음매 노면 미끄러짐', '강풍']::text[], array['시정 불량 시 감속과 점등', '교량 위 급제동 금지']::text[], '해안 지역 훈련 이동 시 안개 예보를 확인한다.', array['c09', 'c16']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z06', '광안대교 일대', '부산 수영·해운대', 35.15, 129.13, 'bridge', array['rain', 'fog']::text[], 3, '해상 교량 구간으로 비와 해무에 의해 노면과 시정이 나빠질 수 있다.', array['우천 시 미끄러움', '해무로 인한 시정 저하', '교통량 많은 구간의 추돌']::text[], array['우천 시 평소 속도의 20% 감속', '안전거리 확보']::text[], '도심 교량 구간은 교통량이 많으므로 대형 차량은 저속·일정 속도를 유지한다.', array['c01', 'c02', 'c09']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z07', '지리산 성삼재 도로', '전남 구례 ~ 전북 남원', 35.31, 127.52, 'mountain', array['fog', 'rain', 'ice']::text[], 4, '굽은 도로가 많은 고지대 도로로, 안개와 결빙이 잦다. 시야가 좁은 커브에서 정면충돌 위험이 있다.', array['연속 급커브', '안개와 노면 결빙', '야생동물 출현']::text[], array['커브 앞 서행', '차로 중앙선을 넘지 않기', '야간·안개 시 상향등 남용 금지']::text[], '산악 지형 훈련 이동 시 도로폭이 좁은 구간에서는 유도원을 배치한다.', array['c03', 'c21', 'c07']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z08', '중부내륙고속도로 문경새재 구간', '경북 문경', 36.78, 128.05, 'highway', array['ice', 'fog']::text[], 4, '산악 지형을 통과하는 고속도로로 겨울철 결빙과 아침 안개가 자주 발생하는 구간으로 알려져 있다.', array['새벽·그늘진 구간의 블랙아이스', '안개로 인한 연쇄 추돌']::text[], array['새벽 시간대 출발 시 속도 하향', '급제동·급핸들 금지']::text[], '새벽 이른 시각 이동은 결빙 가능성이 높아 출발 시각 조정을 검토한다.', array['c15', 'c16', 'c17']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z09', '죽령터널 구간 (중앙고속도로)', '경북 영주 ~ 충북 단양', 36.93, 128.46, 'tunnel', array['snow', 'ice']::text[], 4, '장대터널 입출구는 밝기 차이로 시인성이 떨어지고, 겨울에는 입출구 노면이 얼기 쉽다.', array['터널 입출구 명암 차이', '출구 직후 결빙', '터널 내 사고 시 연쇄 추돌']::text[], array['터널 진입 전 감속과 전조등 점등', '터널 내 차로 변경 금지', '출구 직후 결빙 가능성 대비']::text[], '터널 내 대형 차량이 정차하면 후방 시인성이 낮다. 비상 상황에서는 비상등과 안전표지를 우선 설치한다.', array['c10', 'c12', 'c14']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z10', '인제양양터널 (서울양양고속도로)', '강원 인제 ~ 양양', 38.04, 128.38, 'tunnel', array['night', 'fog']::text[], 3, '국내 최장급 터널로 장시간 단조로운 주행이 이어져 졸음과 속도 감각 저하 위험이 있다.', array['졸음·집중력 저하', '터널 내 속도 초과', '사고 시 대피 지연']::text[], array['터널 진입 전 휴식', '일정 속도 유지', '차간 거리 확보']::text[], '장거리 운행 시 운전자 교대와 휴식 시간을 계획에 반영한다.', array['c10', 'c12']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z11', '잠수교·한강변 도로 일대', '서울 서초·용산', 37.514, 126.996, 'bridge', array['rain']::text[], 5, '한강 수위가 오르면 통제되는 저지대 도로. 집중호우 시 침수 위험이 매우 높다.', array['침수로 인한 시동 꺼짐', '수위 상승 속도 예측 곤란', '물에 잠긴 노면 진입']::text[], array['침수·통제 도로는 절대 진입하지 않음', '우회 경로 확인', '차량이 잠기기 전에 탈출']::text[], '집중호우 시 저지대·하천변 이동은 중단하고 지휘관 판단에 따른다.', array['c01', 'c02']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z12', '오송 인근 지하차도 (침수 위험 예시)', '충북 청주', 36.63, 127.33, 'underpass', array['rain']::text[], 5, '2023년 7월 집중호우 때 지하차도 침수 사고가 발생한 지역이다. 지하차도는 빗물이 한 번에 고이기 쉬워 호우 시 진입을 피해야 한다.', array['급격한 침수', '차량 고립', '탈출 지연']::text[], array['호우 경보 시 지하차도 진입 금지', '진입 전 물이 차 있으면 즉시 우회', '침수 시 차를 버리고 높은 곳으로 대피']::text[], '호우 시 지하차도 통과 이동은 계획 단계부터 배제한다.', array['c14']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z13', '제주 1100도로 일대', '제주 서귀포', 33.36, 126.46, 'mountain', array['fog', 'snow', 'ice']::text[], 3, '한라산 고지대를 가로지르는 도로로 겨울철 적설·결빙과 짙은 안개가 잦다.', array['결빙', '짙은 안개', '굽은 도로']::text[], array['월동장비 확인', '저속 주행과 안전거리 확보']::text[], '도서 지역 훈련 시 고지대 도로의 기상 예보를 우선 확인한다.', array['c04', 'c15']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z14', '철원 전방지역 도로 (예시)', '강원 철원', 38.15, 127.31, 'mountain', array['fog', 'night', 'snow']::text[], 4, '교육용 예시 지점. 전방지역 야간·안개·적설 상황에서의 도로 위험을 학습하기 위한 대표 위치다. 실제 사고다발지점 통계가 아니다.', array['야간 시인성 저하', '안개', '농로·야생동물 출현', '적설']::text[], array['야간에는 속도를 낮추고 전조등 점검', '시야가 막힌 구간에서 서행', '동물 출현 가능 구간 주의']::text[], '훈련 시 소등 운행이 필요한 상황에서도 속도 제한과 유도원 배치로 사고 위험을 낮춘다. 세부 지침은 부대 규정을 따른다.', array['c10', 'c12', 'c21']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z15', '화천 전방지역 산악도로 (예시)', '강원 화천', 38.1, 127.71, 'mountain', array['snow', 'ice', 'night']::text[], 4, '교육용 예시 지점. 겨울철 산악 도로에서 눈·결빙·야간이 겹치는 상황을 학습한다. 실제 사고다발지점 통계가 아니다.', array['결빙 내리막', '굽은 도로', '야간 시인성 저하']::text[], array['내리막 진입 전 감속', '엔진브레이크 활용', '제설 차량 접근에 대비']::text[], '겨울철 훈련 이동 전 경로의 제설·결빙 상태를 확인하고 월동장비를 점검한다.', array['c04', 'c05', 'c15']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z16', '인제 전방지역 도로 (예시)', '강원 인제', 38.07, 128.17, 'mountain', array['snow', 'ice', 'fog']::text[], 4, '교육용 예시 지점. 산악 지형에서 적설·결빙·안개가 반복되는 도로 환경을 학습한다. 실제 사고다발지점 통계가 아니다.', array['적설과 결빙', '안개', '급커브']::text[], array['월동장비 확인', '커브 앞 감속', '안전거리 확보']::text[], '수송대는 선두·후미 차량 간 무전 교신으로 노면 상황을 공유한다.', array['c03', 'c05', 'c06']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z17', '연천·임진강 일대 (예시)', '경기 연천', 38.1, 127.07, 'general', array['fog', 'night', 'rain']::text[], 3, '교육용 예시 지점. 강변 지역의 안개와 집중호우 때 도로 침수·시정 불량 상황을 학습한다. 실제 사고다발지점 통계가 아니다.', array['강변 안개', '집중호우 시 저지대 침수', '야간 시인성 저하']::text[], array['호우 시 하천변·저지대 진입 금지', '안개 시 감속과 점등']::text[], '호우 경보 시 하천 인근 이동은 중단하고 지휘 계통의 판단을 따른다.', array['c01', 'c02', 'c10']::text[]);
insert into public.zones (id,name,region,lat,lng,road_type,climates,risk,description,hazards,prevention,military_note,case_ids) values ('z18', '양구 전방지역 도로 (예시)', '강원 양구', 38.11, 127.99, 'mountain', array['snow', 'night']::text[], 3, '교육용 예시 지점. 겨울 야간 산길 주행에서의 위험을 학습한다. 실제 사고다발지점 통계가 아니다.', array['야간 눈길', '시야가 막힌 커브', '동물 출현']::text[], array['야간에는 속도 하향', '커브 앞 경음·전조등 신호', '서행 유지']::text[], '야간 이동 시 운전자 피로를 관리하고 교대 계획을 세운다.', array['c03', 'c12', 'c21']::text[]);
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-rain', 'weather', 'rain', '비·폭우 시 안전운행', '젖은 노면은 제동거리가 길어지고 수막현상으로 조향·제동이 안 될 수 있다.', array['비가 와서 노면이 젖었으면 최고속도의 20%를 줄이고, 폭우로 가시거리가 100m 이내이면 50%를 줄인다 (도로교통법 시행규칙).', '앞차와의 거리를 평소보다 크게 유지하고, 급제동·급핸들을 피한다.', '타이어 마모·공기압을 출발 전에 점검한다.', '침수된 도로나 지하차도, 하천변 저지대는 진입하지 않는다.', '페인트 표시·맨홀·배수구 위는 더 미끄러우므로 피해서 주행한다.']::text[], '수막현상이 느껴지면 핸들을 고정하고 가속페달에서 서서히 발을 뗀다.');
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-snow', 'weather', 'snow', '눈길 안전운행', '적설은 제동거리를 크게 늘리고, 오르막·내리막에서 차가 미끄러지기 쉽다.', array['눈이 20mm 이상 쌓였다면 최고속도의 50%로 줄인다 (도로교통법 시행규칙).', '월동장비(체인·스노타이어)를 출발 전에 확인하고 장착한다.', '출발과 정지는 천천히, 제동은 미리 부드럽게 한다.', '내리막은 진입 전에 속도를 줄이고 엔진브레이크를 활용한다.', '제설 작업 차량이 반대 차로로 올 수 있으므로 속도와 간격에 여유를 둔다.']::text[], '오르막 중간에 멈추면 다시 오르기 어렵다. 앞차와 간격을 크게 벌려 정지 없이 통과한다.');
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-ice', 'weather', 'ice', '결빙·블랙아이스 대처', '노면이 얼면 눈에 잘 띄지 않아 순식간에 통제력을 잃는다. 다리·터널 출입구·그늘진 곳이 특히 위험하다.', array['노면이 얼어붙은 경우 최고속도의 50%로 줄인다 (도로교통법 시행규칙).', '새벽·밤 시간대와 다리 위, 터널 출입구, 그늘진 커브는 결빙 가능성을 먼저 의심한다.', '미끄러지면 급제동·급가속·급핸들을 피하고 서서히 속도를 줄인다.', '앞차와 간격을 크게 두어 앞차 미끄러짐에 대응할 시간을 확보한다.']::text[], '앞차가 갑자기 흔들리거나 노면이 반짝이면 결빙으로 판단한다.');
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-fog', 'weather', 'fog', '안개 시 안전운행', '시정이 나빠지면 앞차를 늦게 발견해 연쇄 추돌 위험이 커진다.', array['가시거리가 100m 이내이면 최고속도의 50%로 감속한다 (도로교통법 시행규칙).', '전조등(하향등)과 안개등을 켠다. 상향등은 난반사로 시야를 더 해친다.', '차로 변경과 추월을 하지 않는다.', '앞차 후미등을 기준으로 안전거리를 유지하되, 앞차만 따라 과속하지 않는다.', '안전한 곳에서 멈출 때는 도로가 아닌 갓길·휴게소 등으로 이동한다.']::text[], '도로 위에서 정지하면 뒤차가 추돌할 수 있다. 정차가 필요하면 안전한 곳으로 이동한다.');
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-night', 'weather', 'night', '야간 안전운행', '야간에는 시야와 거리감이 줄고 졸음 위험이 커진다.', array['전조등·미등 점검 후 출발하고, 맞은편 차가 있으면 하향등으로 전환한다.', '시야가 닿는 거리 안에서 정지할 수 있는 속도로 주행한다.', '고장·사고 차량은 비상등과 안전표지로 후방에 알린다.', '내비게이션 확인에 시선을 오래 두지 않고, 졸리면 즉시 휴식한다.', '장거리 운행은 운전자를 교대하고 휴식 시간을 계획한다.']::text[], '야간 고속도로의 방치 차량은 늦게 보인다. 전방 멀리까지 주시한다.');
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-highway', 'road', 'highway', '고속도로 안전운행', '고속 주행에서는 작은 실수도 큰 사고로 이어진다.', array['차로 변경은 방향지시등을 먼저 켜고 한 차로씩 한다.', '정체 구간 접근 시 미리 감속하고 안전거리를 둔다.', '고장·사고 시 비상등, 안전표지 설치 후 안전한 곳으로 대피한다.', '졸음이 오면 즉시 졸음쉼터·휴게소를 이용한다.', '비상등은 방향지시등을 대신하지 않는다.']::text[], null);
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-tunnel', 'road', 'tunnel', '터널 안전운행', '입출구의 밝기 차이와 터널 내 사고 시 대피 지연이 위험 요인이다.', array['진입 전 속도를 줄이고 전조등을 켠다.', '터널 안에서는 차로 변경과 추월을 하지 않는다.', '출구 직후 결빙·측풍을 대비한다.', '비상 시 비상등을 켜고 차량을 비상 통로 쪽으로 이동·대피한다.']::text[], '터널 내 사고 차량이 있으면 가능한 한 멀리서 감속·정지한다.');
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-curve', 'road', 'curve', '급커브 구간 안전운행', '곡선 구간의 과속은 차량이 도로 밖으로 밀리거나 중앙선을 넘는 원인이다.', array['커브 진입 전에 속도를 줄이고, 커브 중간에는 제동하지 않는다.', '표지판의 제한속도는 상한이다. 노면 상태가 나쁘면 더 낮춘다.', '급커브에서는 추월하지 않는다.', '대형 차량은 무게중심이 높아 전복 위험이 크므로 특히 감속한다.']::text[], null);
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-mountain', 'road', 'mountain', '산악·굽은 도로 안전운행', '시야가 짧고 중앙선이 없는 구간이 많아 정면충돌과 이탈 사고 위험이 있다.', array['중앙선이 없는 굽은 길은 차로 우측으로 붙고 서행한다.', '시야가 막힌 커브 앞에서는 즉시 정지할 수 있는 속도로 줄인다.', '동물·낙석 가능성을 항상 염두에 둔다.', '도로폭이 좁은 구간은 교행 가능한 지점에서 양보한다.']::text[], null);
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-slope', 'road', 'slope', '내리막·언덕 안전운행', '내리막에서 제동을 반복하면 브레이크가 과열되고, 눈·얼음 위에서는 쉽게 미끄러진다.', array['내리막 진입 전에 변속기를 낮추고 엔진브레이크를 활용한다.', '발 브레이크를 길게 밟지 말고 짧게 나눠 밟는다.', '앞차와 거리를 충분히 확보한다.', '눈길 오르막은 정지 없이 통과할 수 있게 간격을 벌린다.']::text[], null);
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-bridge', 'road', 'bridge', '교량·해안도로 안전운행', '교량은 도로보다 먼저 얼고 측풍과 안개의 영향을 크게 받는다.', array['교량 진입 전 결빙·강풍·안개 정보를 확인한다.', '측풍이 강하면 핸들을 단단히 잡고 속도를 낮춘다.', '교량 위에서는 급제동·급차로 변경을 하지 않는다.']::text[], null);
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-underpass', 'road', 'underpass', '지하차도 안전운행', '빗물이 한 번에 고이거나 폭설 시 미끄러워 위험하다.', array['호우·폭설 시 지하차도 진입을 피하고 우회한다.', '진입 전 물이 고여 있으면 들어가지 않는다.', '차량이 잠기기 시작하면 차를 버리고 높은 곳으로 대피한다.', '눈길 지하차도에서는 정차 차량을 일찍 발견할 수 있도록 감속한다.']::text[], null);
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-urban', 'road', 'urban', '도심·교차로 안전운행', '보행자·이륜차·신호 없는 교차로에서는 예기치 않은 충돌이 잦다.', array['신호 없는 교차로는 감속하고 직진 차량과 이륜차를 먼저 확인한다.', '보행자가 많은 골목·시장 구간은 서행한다.', '출발 전 제동장치와 페달 상태를 점검한다.', '사고 시 즉시 정지하고 구호 조치를 한다.']::text[], null);
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-general', 'road', 'general', '일반도로 안전운행', '차로 변경·합류·정차 후 출발에서의 확인 부족이 사고로 이어진다.', array['갓길이나 부대 진입로에서 본선에 합류할 때는 정지 후 후방과 좌우를 확인한다.', '차로 변경 전 미러와 육안으로 사각지대를 확인한다.', '방향지시등으로 항상 의도를 알린다.']::text[], null);
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-mil-vehicle', 'military', 'vehicle', '군 차량 특성과 안전운행', '군용 트럭·버스는 중량과 무게중심, 사각지대 때문에 일반 승용차와 다르게 운전해야 한다.', array['적재 상태(인원·화물)에 따라 제동거리가 크게 늘어남을 고려해 감속한다.', '화물은 반드시 고정하고, 무게중심이 높은 차량은 커브에서 더 감속한다.', '후진·좁은 구간·시장 등 보행자 혼재 지역에서는 유도원을 배치한다.', '사각지대가 넓으므로 미러 확인에 더해 육안 확인과 유도원을 활용한다.']::text[], '부대별 운행 규정과 안전수칙이 있는 경우 해당 규정을 우선한다.');
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-mil-maint', 'military', 'maintenance', '운행 전 점검', '제동장치·타이어·등화장치 불량은 현장에서 수습할 수 없다.', array['제동 페달 유격과 제동력, 공기압(대형 차량), 타이어 마모를 확인한다.', '전조등·미등·방향지시등·비상등 작동을 확인한다.', '와이퍼·워셔액·성에 제거 기능을 점검한다.', '월동장비(체인)와 비상 삼각대·소화기를 비치한다.']::text[], null);
insert into public.tips (id,"group",key,title,summary,steps,caution) values ('t-mil-convoy', 'military', 'convoy', '수송대 편성 운행', '다수 차량이 이동할 때는 연쇄 추돌과 속도 불균형을 관리해야 한다.', array['차간 거리를 기상 조건에 따라 평소보다 늘리고 속도를 통일한다.', '선두·후미 간 무전으로 노면·시정 상황을 공유한다.', '기상 악화 시 출발 시각·경로를 조정하고, 위험하면 이동을 중단한다.', '장거리 이동은 운전자 교대와 휴식 시간을 계획에 반영한다.']::text[], '음주 후 운전은 어떤 경우에도 금지한다. 복귀 시 대리운전·대중교통을 이용한다.');
